INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7211832, 1111537, 96751, '<td valign="top">Looks metallic!!</td>', 'Looks metallic!!', '2014-05-03 13:18:07.000000', NULL, 1),
(7211833, 1111535, 60173, '<td valign="top">That''s about the roughest looking ladybug I''ve ever seen. Did you grunge him, or is he just a grandpa ladybug? Also, the tones in your background are yummy.</td>', 'That''s about the roughest looking ladybug I''ve ever seen. Did you grunge him, or is he just a grandpa ladybug? Also, the tones in your background are yummy.', '2014-05-03 13:18:20.000000', NULL, 1),
(7211848, 1111579, 43463, '<td valign="top">Voted earlier coming back to comment. <br/> <br/>Fantastic B&amp;W tones and compositional crop bring me right to your main subject - the smiling girl with her cuddled cat. Very lovely girl and candid moment caught here. Lighting and details are spot on - a little blurred for the cat - maybe cat moved while shot was taken which a higher ISO will take care of and/or a higher aperature 7.1 or higher to get a greater DOF (although you may not get that nice bokeh background so it might just be a toss-up to what is best). None-the-less maybe a little blur is not so bad - life happens and movement gives this a feeling of being there at that moment to see and observe the beauty of the moment a girl cradling her beloved pet.</td>', 'Voted earlier coming back to comment.  Fantastic B&W tones and compositional crop bring me right to your main subject - the smiling girl with her cuddled cat. Very lovely girl and candid moment caught here. Lighting and details are spot on - a little blurred for the cat - maybe cat moved while shot was taken which a higher ISO will take care of and/or a higher aperature 7.1 or higher to get a greater DOF (although you may not get that nice bokeh background so it might just be a toss-up to what is best). None-the-less maybe a little blur is not so bad - life happens and movement gives this a feeling of being there at that moment to see and observe the beauty of the moment a girl cradling her beloved pet.', '2014-05-03 14:52:12.000000', NULL, 1),
(7211849, 1111583, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>Wow! I love the way the yellow flowers just pop off of the dreamy shades of blue and green of the meadows in the backdrop. The colors make for a magical mood. Well done.</td>', 'Voted earlier coming back to comment. Wow! I love the way the yellow flowers just pop off of the dreamy shades of blue and green of the meadows in the backdrop. The colors make for a magical mood. Well done.', '2014-05-03 14:53:52.000000', NULL, 1),
(7211879, 1111506, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>There is such charm and time adorned beauty in streets of small ancient/old towns. There is history in those worn steps - walking in the footsteps of the past one can imagine the laughter, hopes and tears that once passed by these walls. Love the processing for it looks like an old master''s oil painting.</td>', 'Voted earlier coming back to comment. There is such charm and time adorned beauty in streets of small ancient/old towns. There is history in those worn steps - walking in the footsteps of the past one can imagine the laughter, hopes and tears that once passed by these walls. Love the processing for it looks like an old master''s oil painting.', '2014-05-03 18:30:25.000000', NULL, 1),
(7211882, 1111510, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>One of my favorite flowers. Love all the fabulous detail and color that explodes from this composition. Lighting fully complements this beautiful bloom. Nicely done macro work!</td>', 'Voted earlier coming back to comment. One of my favorite flowers. Love all the fabulous detail and color that explodes from this composition. Lighting fully complements this beautiful bloom. Nicely done macro work!', '2014-05-03 18:33:48.000000', NULL, 1),
(7211949, 1111597, 86447, '<td valign="top">Give me six words that describe your image to you (if you didn''t know the challenge topic).<br/> <br/>GO!<br/> <br/>Did you list "beauty" as one of them?<br/> <br/> Arg.  I didn''t either.<br/> <br/>I came up with:<br/> <br/>Balance.<br/>Scarf.<br/>Arms.<br/>Contentment.<br/>Background.<br/>Freedom.<br/> <br/> <br/>6 from me.</td>', 'Give me six words that describe your image to you (if you didn''t know the challenge topic). GO! Did you list "beauty" as one of them?  Arg.  I didn''t either. I came up with: Balance.Scarf.Arms.Contentment.Background.Freedom.  6 from me.', '2014-05-03 21:48:50.000000', NULL, 1),
